// Inventario de demostracion; en produccion: consulta SQL o API.
const stock = { 'camara a7s': 3, 'optica 35mm': 2, 'tripode': 6 };
const q = ($input.first().json.query || '').toLowerCase();
const unidades = stock[q];
return [{ json: { articulo: q, disponible: unidades ?? 0,
  encontrado: unidades !== undefined } }];
